import{_ as d,o as r,c as a,ah as e}from"./chunks/framework.DuX8SFU5.js";const b=JSON.parse('{"title":"AM_NODE_V2 — CAN-контроллер нагрузок и датчиков","description":"","frontmatter":{"title":"AM_NODE_V2 — CAN-контроллер нагрузок и датчиков","device":{"name":"AM_NODE_V2","title":"CAN-контроллер нагрузок и датчиков","summary":"Узел ввода-вывода машины. Управляет клапанами и другими нагрузками, опрашивает датчики и обменивается с системой управления по CAN.","status":"prototype","image":"am_node_v2_enclosure.webp","specs":["4 выхода LOAD","8 входов SENS","4 входа 4–20 мА","CAN · DroneCAN","24 В"],"order":1},"pdf":"/pdf/AM_NODE_V2_overview.pdf"},"headers":[],"relativePath":"am_node_v2/index.md","filePath":"am_node_v2/README.md"}'),o={name:"am_node_v2/index.md"};function h(n,t,i,s,l,_){return r(),a("div",null,[...t[0]||(t[0]=[e('<h2 id="возможности" tabindex="-1">Возможности <a class="header-anchor" href="#возможности" aria-label="Permalink to &quot;Возможности&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Возможности платформы</th></tr></thead><tbody><tr><td>Выходы управления</td><td>4 канала LOAD: включение/выключение или ШИМ; нагрузка подбирается по электрическим параметрам</td></tr><tr><td>Дискретные сигналы</td><td>8 каналов SENS; режим для PNP- или NPN-датчиков задаётся конфигурацией</td></tr><tr><td>Питание датчиков</td><td>Программное включение питания датчиков отдельно от сигнальных входов SENS</td></tr><tr><td>Токовые измерения</td><td>4 входа C_SENS для датчиков 4–20 мА; подключение требует проверки исполнения и калибровки</td></tr><tr><td>Электрическая диагностика</td><td>Ток и напряжение цепей нагрузки и ручного управления; контроль напряжения и тока питания</td></tr><tr><td>Ручное управление</td><td>Контроль штатного сигнала; передача штатной команды на клапан при отказе платы (bypass)</td></tr><tr><td>Основное питание</td><td>24 В номинально, с внешней защитой; рабочий диапазон уточняется для исполнения</td></tr><tr><td>Габариты платы</td><td>82,5 × 98,5 мм; размеры корпуса согласуются отдельно</td></tr></tbody></table><h2 id="исполнения" tabindex="-1">Исполнения <a class="header-anchor" href="#исполнения" aria-label="Permalink to &quot;Исполнения&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Интерфейсы</th><th>H7</th><th>F103</th></tr></thead><tbody><tr><td>CAN</td><td>2 интерфейса</td><td>1 интерфейс</td></tr><tr><td>USB-C</td><td>есть</td><td>нет</td></tr><tr><td>Ethernet 10/100 Мбит/с</td><td>есть на плате</td><td>нет</td></tr></tbody></table><p>Для внешнего Ethernet-подключения исполнения H7 нужно согласовать интерфейсную обвязку и разъём. Состав и режимы ввода-вывода подтверждаются для выбранной сборки: исполнения H7 и F103 не равноценны по функциям.</p><h2 id="протоколы" tabindex="-1">Протоколы <a class="header-anchor" href="#протоколы" aria-label="Permalink to &quot;Протоколы&quot;">​</a></h2><p>В базовой конфигурации прошивки используется <strong>DroneCAN</strong>. Интеграция с <strong>CANopen</strong> требует согласования профиля устройства и сообщений; универсальный профиль ввода-вывода не заявлен. Скорость CAN и период обмена задаются под сеть машины.</p><h2 id="применение" tabindex="-1">Применение <a class="header-anchor" href="#применение" aria-label="Permalink to &quot;Применение&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Задача машины</th><th>Подключение и функция</th></tr></thead><tbody><tr><td>Зажим трубы, фиксация механизма</td><td>Катушки гидрораспределителя и концевые датчики: команды открытия и закрытия, подтверждение положения</td></tr><tr><td>Подача бурового инструмента</td><td>ШИМ-управление пропорциональным клапаном; закон регулирования задаёт система управления машины</td></tr><tr><td>Контроль гидросистемы</td><td>Датчик давления с токовым выходом: измерение для индикации, записи или алгоритма управления</td></tr><tr><td>Модернизация ручного управления</td><td>Подключение между штатным источником команды и клапаном; измерение сигнала и выбор режима по согласованной схеме</td></tr><tr><td>Сигнализация и электроприводы</td><td>Маяк или звуковой сигнализатор; электропривод через совместимый драйвер или реле</td></tr></tbody></table><h2 id="подключаемое-оборудование" tabindex="-1">Подключаемое оборудование <a class="header-anchor" href="#подключаемое-оборудование" aria-label="Permalink to &quot;Подключаемое оборудование&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Оборудование</th><th>Что измеряет или делает</th><th>Подключение</th></tr></thead><tbody><tr><td>Тросовый датчик перемещения</td><td>Ход каретки подачи, положение подвижного узла</td><td>Выход 4–20 мА → C_SENS; импульсный выход → SENS с проверкой уровней и частоты</td></tr><tr><td>Инкрементальный энкодер</td><td>Обороты, частота вращения, перемещение через мерное колесо</td><td>A/B → SENS после проверки уровней, частоты и декодирования прошивкой</td></tr><tr><td>Потенциометрический датчик</td><td>Положение штока, угол рычага</td><td>Через внешний преобразователь в 4–20 мА или модуль аналогового ввода</td></tr><tr><td>Джойстик оператора</td><td>Направление и скорость подачи, контроль ручной команды</td><td>Контакты → SENS; штатная команда клапану → вход контроля команды</td></tr><tr><td>Датчик давления</td><td>Давление в гидролинии подачи или зажима</td><td>Выход 4–20 мА → C_SENS</td></tr><tr><td>Клапан, маяк, сигнализатор</td><td>Исполнительные устройства и сигнализация</td><td>LOAD: включение/выключение или ШИМ</td></tr></tbody></table><p>Разные типы оборудования сочетаются в пределах 4 LOAD, 8 SENS и 4 C_SENS выбранного исполнения. Энкодер A/B занимает 2 входа SENS, A/B/Z — 3; двухкатушечный клапан занимает 2 выхода LOAD.</p><h2 id="условия-интеграции" tabindex="-1">Условия интеграции <a class="header-anchor" href="#условия-интеграции" aria-label="Permalink to &quot;Условия интеграции&quot;">​</a></h2><p><strong>Датчики.</strong> Для PNP/NPN-датчиков, сухих контактов и импульсных выходов подбирается схема подключения. NPN требует внешней подтяжки, сигналы 0–10 В — согласования. Для энкодеров проверяются частота и поддержка декодирования.</p><p><strong>Нагрузки.</strong> Проверяются рабочий и пусковой ток, напряжение и защита. ШИМ применим к совместимой нагрузке; прямое питание двигателя и реверс не заявлены. Тайм-аут CAN и состояние выходов при отказе задаются в проекте.</p><p><strong>Диагностика.</strong> Ток катушки характеризует электрическую цепь, движение подтверждают датчики. Обрыв сигнального провода не всегда отличим от штатного состояния датчика. Аварийный останов выполняется независимой цепью.</p><h2 id="следующии-шаг" tabindex="-1">Следующий шаг <a class="header-anchor" href="#следующии-шаг" aria-label="Permalink to &quot;Следующий шаг&quot;">​</a></h2><p>Для подбора нужны параметры нагрузок и датчиков, питание, протокол CAN и рабочий цикл. Допустимые токи, диапазон температур и степень защиты корпуса определяются для конкретного исполнения. Подробные характеристики, разъёмы и распиновка — в <a href="./datasheet">даташите</a>.</p>',18)])])}const p=d(o,[["render",h]]);export{b as __pageData,p as default};
